create unique index IDX_HUNTTECH_POSSIBLE_NAMES_UK_POSSIBLE_NAME on HUNTTECH_POSSIBLE_NAMES (POSSIBLE_NAME) where DELETE_TS is null ;
create index IDX_HUNTTECH_POSSIBLE_NAMES_ON_POSITION on HUNTTECH_POSSIBLE_NAMES (POSITION_ID);
create index IDX_HUNTTECH_POSSIBLE_NAMES_EN_NAME_POSITION on HUNTTECH_POSSIBLE_NAMES (POSSIBLE_EN_NAME_POSIION);
create index IDX_HUNTTECH_POSSIBLE_NAMES_POSSIBLE_NAME on HUNTTECH_POSSIBLE_NAMES (POSSIBLE_NAME);
